83	 */
84	
85	@RestController
86	@CrossOrigin(exposedHeaders = "errors, content-type")
87	@RequestMapping("/api")
88	public class OwnerRestControllerV1 implements OwnersApi {
89	
90	    /**
91	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
92	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
93	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
94	     */
95	    private static final Pattern EMAIL_PATTERN =
96	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
97	
98	    /** Dedicated audit logger; carries owner lifecycle side-effects. */
99	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
100	
101	    /** Dedicated notification logger; carries the welcome notification enqueued on create. */
102	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
103	
104	    /** Marker naming the structured audit event emitted when an owner is created. */
105	    private static final String OWNER_CREATED_EVENT = "OWNER_CREATED";
106	
107	    /**
108	     * Monotonically increasing sequence stamped onto each structured create event, so consumers
109	     * can order events across creates. Shared across all creates handled by this application.
110	     */
111	    private static final AtomicLong CREATE_EVENT_SEQ = new AtomicLong();
112	
113	    /** Serializes structured audit events to compact JSON. */
114	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
115	
116	    /** Request header carrying the client-supplied idempotency key for creates. */
117	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
118	
119	    /**
120	     * Remembers the owner created for each already-seen {@code Idempotency-Key}, so a create that
121	     * repeats with the same key returns the originally created owner (200) instead of creating a
122	     * duplicate. Keyed by the raw header value; the mapped value is the created owner's id.
123	     */
124	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
125	
126	    private final ClinicService clinicService;
127	
128	    private final OwnerMapper ownerMapper;
129	
130	    private final PetMapper petMapper;
131	
132	    private final VisitMapper visitMapper;
133	
134	    public OwnerRestControllerV1(ClinicService clinicService,
135	                                 OwnerMapper ownerMapper,
136	                                 PetMapper petMapper,
137	                                 VisitMapper visitMapper) {
138	        this.clinicService = clinicService;
139	        this.ownerMapper = ownerMapper;
140	        this.petMapper = petMapper;
141	        this.visitMapper = visitMapper;
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
147	        Collection<Owner> owners;
148	        if (lastName != null) {
149	            owners = this.clinicService.findOwnerByLastName(lastName);
150	        } else {
151	            owners = this.clinicService.findAllOwners();
152	        }
153	        if (owners.isEmpty()) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
172	        // Idempotent create: if this request repeats an already-seen 'Idempotency-Key', return the
173	        // owner created the first time (200) rather than creating a duplicate.
174	        String idempotencyKey = idempotencyKey();
175	        if (idempotencyKey != null) {
176	            Integer existingId = idempotentCreates.get(idempotencyKey);
177	            if (existingId != null) {
178	                Owner existing = this.clinicService.findOwnerById(existingId);
179	                if (existing != null) {
180	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
181	                }
182	            }
183	        }
184	        List<String> missingFields = new ArrayList<>();
185	        if (isBlank(ownerFieldsDto.getFirstName())) {
186	            missingFields.add("firstName");
187	        }
188	        if (isBlank(ownerFieldsDto.getLastName())) {
189	            missingFields.add("lastName");
190	        }
191	        // Normalize whichever address form was supplied and fold it into the DTO: the structured
192	        // 'addressLine1'/'addressLine2' win when a non-blank 'addressLine1' is present, otherwise the
193	        // flat 'address' is used. The composed value is stored back into 'address' so every reader of
194	        // the owner's address sees the effective (structured-or-flat) value.
195	        applyAddress(ownerFieldsDto);
196	        if (isBlank(ownerFieldsDto.getAddress())) {
197	            missingFields.add("address");
198	        }
199	        if (isBlank(ownerFieldsDto.getCity())) {
200	            missingFields.add("city");
201	        }
202	        if (isBlank(ownerFieldsDto.getTelephone())) {
203	            missingFields.add("telephone");
204	        }
205	        if (!missingFields.isEmpty()) {
206	            throw new MissingOwnerFieldsException(missingFields);
207	        }
208	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
209	        LocalDate suppliedRegistrationDate = ownerFieldsDto.getRegistrationDate();
210	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
211	            throw new FutureRegistrationDateException(
212	                "registrationDate must not be later than the server date");
213	        }
214	        LocalDate registrationDate = toBusinessDay(
215	            suppliedRegistrationDate != null
216	                ? suppliedRegistrationDate
217	                : LocalDate.now());
218	        long registeredOnDay = this.clinicService.findAllOwners().stream()
219	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
220	            .count();
221	        if (registeredOnDay >= 100) {
222	            throw new DailyRegistrationLimitException(
223	                "100 or more owners have already been registered today");
224	        }
225	        boolean bulkSignupWarning = registeredOnDay > 80;
226	        String city = ownerFieldsDto.getCity();
227	        long ownersInCity = this.clinicService.findAllOwners().stream()
228	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
229	            .count();
230	        if (ownersInCity >= 50) {
231	            throw new CityAtCapacityException(
232	                "the owner's city already contains 50 or more owners");
233	        }
234	        // Soft warning as the city approaches its hard capacity of 50: flag owners created while
235	        // their city already holds between 40 and 49 owners. Computed on create and returned
236	        // unchanged thereafter.
237	        boolean capacityWarning = ownersInCity >= 40;
238	        String telephone = toE164(ownerFieldsDto.getTelephone());
239	        ownerFieldsDto.setTelephone(telephone);
240	        String email = normalizeEmail(ownerFieldsDto.getEmail());
241	        ownerFieldsDto.setEmail(email);
242	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
243	        String postcode = ownerFieldsDto.getPostcode();
244	        // Deterministic household id: owners with the same normalized last name and postcode
245	        // share it automatically, regardless of creation order. It is no longer created by the
246	        // 'sharesHousehold' flag; that flag now only bypasses the duplicate block below.
247	        String householdId = householdId(lastName, postcode);
248	        // The household is keyed on (last name, postcode), so its existing members are the
249	        // existing owners with the same computed household id. Both the duplicate block and the
250	        // household size below key off this value.
251	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
252	            .filter(existing -> !existing.isDeleted())
253	            .filter(existing -> householdId.equals(
254	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode())))
255	            .toList();
256	        // A second owner in an existing household is admitted as a household member; their
257	        // membership level is capped below (level-ceiling rule) rather than rejected.
258	        // Single, consolidated duplicate check: reject only when the new owner's whole derived
259	        // identity key (SHA-256 over telephone|email|soundex(lastName)) equals an existing,
260	        // non-deleted owner's. This single identity key is the only 409; there is no separate
261	        // household-duplicate rejection keyed off the computed householdId.
262	        String newLastName = ownerFieldsDto.getLastName();
263	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, newLastName);
264	        boolean identityInUse = this.clinicService.findAllOwners().stream()
265	            .filter(existing -> !existing.isDeleted())
266	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
267	                existing.getTelephone(), existing.getEmail(), existing.getLastName())));
268	        if (identityInUse) {
269	            throw new DuplicateIdentityException(
270	                "an owner with the same identity key already exists");
271	        }
272	        // Soft match: not a hard duplicate, but shares a household signature with an existing,
273	        // non-deleted owner — the same last-name Soundex and the same postcode while the identity
274	        // key differs (e.g. same last name and postcode but a different telephone). Such an owner
275	        // is still created (201) but flagged as a possible duplicate of the earliest matching owner
276	        // so it can be reviewed rather than rejected.
277	        String newSoundex = IdentityKeyDeriver.soundex(newLastName);
278	        Integer softMatchOf = this.clinicService.findAllOwners().stream()
279	            .filter(existing -> !existing.isDeleted())
280	            .filter(existing -> !identityKey.equals(IdentityKeyDeriver.identityKey(
281	                existing.getTelephone(), existing.getEmail(), existing.getLastName())))
282	            .filter(existing -> newSoundex.equals(IdentityKeyDeriver.soundex(existing.getLastName())))
283	            .filter(existing -> Objects.equals(postcode, existing.getPostcode()))
284	            .map(Owner::getId)
285	            .min(Integer::compareTo)
286	            .orElse(null);
287	        HttpHeaders headers = new HttpHeaders();
288	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
289	        owner.setRegistrationDate(registrationDate);
290	        owner.setMemberId(deduplicateMemberId(
291	            memberId(owner.getPostcode(), owner.getTelephone(), owner.getLastName(),
292	                owner.getRegistrationDate())));
293	        owner.setHouseholdId(householdId);
294	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
295	        owner.setBulkSignupWarning(bulkSignupWarning);
296	        owner.setCapacityWarning(capacityWarning);
297	        // Household size after this create: existing members plus the owner being created.
298	        owner.setHouseholdSize(householdMembers.size() + 1);
299	        // Level-ceiling: the new owner's membership level cannot exceed one above the current
300	        // maximum level among their existing household members. With no existing member no cap
301	        // applies. The (possibly capped) level is stored so it is returned on create and on read.
302	        int naturalLevel = MembershipPointsDeriver.membershipLevel(
303	            MembershipPointsDeriver.membershipPoints(owner));
304	        int cappedLevel = naturalLevel;
305	        if (!householdMembers.isEmpty()) {
306	            int maxMemberLevel = householdMembers.stream()
307	                .mapToInt(MembershipPointsDeriver::effectiveMembershipLevel)
308	                .max()
309	                .orElseThrow();
310	            cappedLevel = Math.min(naturalLevel, maxMemberLevel + 1);
311	        }
312	        owner.setMembershipLevel(cappedLevel);
313	        // Flag a soft match (same last-name Soundex and postcode as an existing owner, but a
314	        // different identity key) as a possible duplicate of the earliest such owner; a create
315	        // with no soft match is left unflagged.
316	        owner.setPossibleDuplicate(softMatchOf != null);
317	        owner.setPossibleDuplicateOf(softMatchOf);
318	        owner.setDeleted(false);
319	        this.clinicService.saveOwner(owner);
320	        if (idempotencyKey != null) {
321	            idempotentCreates.put(idempotencyKey, owner.getId());
322	        }
323	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
324	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
325	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
326	            ownerDto.getMembershipLevel());
327	        emitOwnerCreatedEvent(owner, ownerDto);
328	        // Enqueue a welcome notification for the newly created owner: emit a NOTIFY line carrying
329	        // the owner's id and memberId so the notification pipeline can address the welcome.
330	        NOTIFY.info("welcome notification enqueued: ownerId={} memberId={}",
331	            owner.getId(), owner.getMemberId());
332	        headers.setLocation(UriComponentsBuilder.newInstance()
333	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
334	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
335	    }
336	
337	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
338	    @Override
339	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
340	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
341	        if (currentOwner == null) {
342	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
343	        }
344	        applyAddress(ownerFieldsDto);
345	        currentOwner.setAddress(ownerFieldsDto.getAddress());
346	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
347	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
348	        currentOwner.setCity(ownerFieldsDto.getCity());
349	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
350	        currentOwner.setLastName(ownerFieldsDto.getLastName());
351	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
352	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
353	        this.clinicService.saveOwner(currentOwner);
354	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
355	    }
356	
357	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
358	    @Transactional
359	    @Override
360	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
361	        Owner owner = this.clinicService.findOwnerById(ownerId);
362	        if (owner == null) {
363	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
364	        }
365	        owner.setDeleted(true);
366	        this.clinicService.saveOwner(owner);
367	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
368	    }
369	
370	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
371	    @Override
372	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
373	        Owner owner = this.clinicService.findOwnerById(ownerId);
374	        if (owner == null) {
375	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
376	        }
377	        HttpHeaders headers = new HttpHeaders();
378	        Pet pet = petMapper.toPet(petFieldsDto);
379	        owner.setId(ownerId);
380	        pet.setOwner(owner);
381	        pet.getType().setName(null);
382	        this.clinicService.savePet(pet);
383	        PetDto petDto = petMapper.toPetDto(pet);
384	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
385	            .buildAndExpand(pet.getId()).toUri());
386	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
387	    }
388	
389	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
390	    @Override
391	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
392	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
393	        if (currentOwner != null) {
394	            Pet currentPet = this.clinicService.findPetById(petId);
395	            if (currentPet != null) {
396	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
397	                currentPet.setName(petFieldsDto.getName());
398	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
399	                this.clinicService.savePet(currentPet);
400	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
401	            }
402	        }
403	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
404	    }
405	
406	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
407	    @Override
408	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
409	        HttpHeaders headers = new HttpHeaders();
410	        Visit visit = visitMapper.toVisit(visitFieldsDto);
411	        Pet pet = new Pet();
412	        pet.setId(petId);
413	        visit.setPet(pet);
414	        this.clinicService.saveVisit(visit);
415	        VisitDto visitDto = visitMapper.toVisitDto(visit);
416	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
417	            .buildAndExpand(visit.getId()).toUri());
418	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
419	    }
