421	
422	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
423	    @Override
424	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
425	        Owner owner = this.clinicService.findOwnerById(ownerId);
426	        if (owner != null) {
427	            Pet pet = owner.getPet(petId);
428	            if (pet != null) {
429	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
430	            }
431	        }
432	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
433	    }
434	
435	    private static boolean isBlank(String value) {
436	        return value == null || value.isBlank();
437	    }
438	
439	    /**
440	     * Returns the {@code Idempotency-Key} header of the current request, or {@code null} when the
441	     * header is absent, blank, or there is no bound request. Read from the request context so the
442	     * generated {@link OwnersApi#addOwner} signature is left untouched.
443	     */
444	    private static String idempotencyKey() {
445	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs)) {
446	            return null;
447	        }
448	        String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
449	        return isBlank(key) ? null : key;
450	    }
451	
452	    /**
453	     * The fixed public-holiday calendar. A registration date that lands on any of these dates is
454	     * rolled forward, just as a weekend is, to the next non-holiday business day.
455	     */
456	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
457	        LocalDate.of(2026, 1, 1),
458	        LocalDate.of(2026, 1, 26),
459	        LocalDate.of(2026, 4, 25),
460	        LocalDate.of(2026, 12, 25),
461	        LocalDate.of(2026, 12, 28));
462	
463	    /**
464	     * Rolls a registration date forward to the next business day: when it falls on a Saturday, a
465	     * Sunday or a listed public holiday it is advanced one day at a time until a non-holiday weekday
466	     * is reached; an unaffected weekday is returned unchanged. This is applied to the effective
467	     * registration date (whether supplied in the request or defaulted to the server date), so every
468	     * value derived from the registration date sees the adjusted business day.
469	     */
470	    private static LocalDate toBusinessDay(LocalDate date) {
471	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
472	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
473	                || PUBLIC_HOLIDAYS.contains(date)) {
474	            date = date.plusDays(1);
475	        }
476	        return date;
477	    }
478	
479	    /**
480	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
481	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
482	     * lower-cased so that last names are compared case-insensitively.
483	     */
484	    private static String normalizeHousehold(String value) {
485	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
486	    }
487	
488	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
489	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
490	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
491	
492	    /**
493	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
494	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
495	     * upper-cased, and common street-type abbreviations are expanded token-by-token
496	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
497	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
498	     * used for every address comparison (household-duplicate detection and the shared household id).
499	     */
500	    private static String normalizeAddress(String value) {
501	        if (value == null) {
502	            return "";
503	        }
504	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
505	        if (collapsed.isEmpty()) {
506	            return "";
507	        }
508	        String[] tokens = collapsed.split(" ");
509	        StringBuilder sb = new StringBuilder();
510	        for (int i = 0; i < tokens.length; i++) {
511	            if (i > 0) {
512	                sb.append(' ');
513	            }
514	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
515	        }
516	        return sb.toString();
517	    }
518	
519	    /**
520	     * Folds an owner's supplied address into its canonical stored form on the given DTO, preferring
521	     * the structured fields when present. When a non-blank {@code addressLine1} is supplied, it and an
522	     * optional {@code addressLine2} are normalized ({@link #normalizeAddress}) and kept as the
523	     * structured lines; the flat {@code address} is set to the composed value ({@code addressLine1},
524	     * plus a single space and {@code addressLine2} when the second line is present). Otherwise the
525	     * structured lines are cleared and the flat {@code address} is set to the normalized flat input.
526	     * The resulting {@code address} is the effective value every address reader sees, and is blank
527	     * only when neither an {@code addressLine1} nor a flat {@code address} was supplied.
528	     */
529	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
530	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
531	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
532	        if (!isBlank(line1)) {
533	            ownerFieldsDto.setAddressLine1(line1);
534	            ownerFieldsDto.setAddressLine2(isBlank(line2) ? null : line2);
535	            ownerFieldsDto.setAddress(isBlank(line2) ? line1 : line1 + " " + line2);
536	        } else {
537	            ownerFieldsDto.setAddressLine1(null);
538	            ownerFieldsDto.setAddressLine2(null);
539	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
540	        }
541	    }
542	
543	    /**
544	     * Derives the stable version-2 {@code householdId} shared by all owners in a household: the
545	     * first 12 hex characters of SHA-256 over
546	     * {@code 'V2' + '|' + normalizedLastName + '|' + postcode}. It is a pure, deterministic function
547	     * of the normalized last name and postcode (with the fixed {@code 'V2'} version tag mixed in), so
548	     * every owner that shares those values maps to the same identifier regardless of creation order,
549	     * while no value version 1 produced is produced again. A {@code null} postcode contributes the
550	     * empty string.
551	     */
552	    private static String householdId(String normalizedLastName, String postcode) {
553	        String key = IDENTITY_VERSION_TAG + "|" + normalizedLastName
554	            + "|" + (postcode == null ? "" : postcode);
555	        return sha256Hex12(key);
556	    }
557	
558	    /** The first 12 lower-case hex characters (6 bytes) of the SHA-256 digest of {@code s}. */
559	    private static String sha256Hex12(String s) {
560	        try {
561	            byte[] digest = MessageDigest.getInstance("SHA-256")
562	                .digest(s.getBytes(StandardCharsets.UTF_8));
563	            StringBuilder sb = new StringBuilder(12);
564	            for (int i = 0; i < 6; i++) {
565	                sb.append(String.format("%02x", digest[i]));
566	            }
567	            return sb.toString();
568	        }
569	        catch (NoSuchAlgorithmException e) {
570	            throw new IllegalStateException("SHA-256 not available", e);
571	        }
572	    }
573	
574	    /**
575	     * Emits the immutable structured {@code OWNER_CREATED} event to the {@code AUDIT} logger as a
576	     * compact JSON object. Under schema version 2 the object is
577	     * {@code {schemaVersion, seq, ownerId, memberId, membershipLevel, ownerSegment, event}}, where
578	     * {@code schemaVersion} is the fixed integer {@code 2}. {@code seq} is a process-wide
579	     * monotonically increasing sequence across creates. The event carries the owner's current
580	     * version-2 primary identifier via {@link #primaryIdentifier(Owner)} — the memberId — and the
581	     * owner segment recomputed from that version-2 identity, so consumers always see the identifier
582	     * and segment in force.
583	     */
584	    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
585	        Map<String, Object> event = new LinkedHashMap<>();
586	        event.put("schemaVersion", 2);
587	        event.put("seq", CREATE_EVENT_SEQ.incrementAndGet());
588	        event.put("ownerId", owner.getId());
589	        event.put("memberId", primaryIdentifier(owner));
590	        event.put("membershipLevel", ownerDto.getMembershipLevel());
591	        event.put("ownerSegment", ownerDto.getOwnerSegment());
592	        event.put("event", OWNER_CREATED_EVENT);
593	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
594	    }
595	
596	    /**
597	     * The owner's current primary identifier carried by structured audit events: the unified
598	     * {@code memberId}.
599	     */
600	    private static String primaryIdentifier(Owner owner) {
601	        return owner.getMemberId();
602	    }
603	
604	    /**
605	     * The fixed version tag mixed into the version-2 owner identity (the region embedded inside the
606	     * identifiers, the householdId, the identityKey and the memberId), so no version-2 value
607	     * reproduces the value version 1 would have produced.
608	     */
609	    private static final String IDENTITY_VERSION_TAG = "V2";
610	
611	    /**
612	     * Builds the version-2 {@code memberId} assigned to a new owner, formatted
613	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the version-2 region code embedded
614	     * inside the identifier - the fixed {@code 'V2'} version tag followed by the region derived from
615	     * the owner's postcode ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}), e.g.
616	     * {@code 'V2NSW'}; {@code FY} is the two-digit fiscal year of the business-day-adjusted
617	     * registration date (the fiscal year starts on 1 July); {@code HASH8} is the first 8 upper-case
618	     * hex characters of SHA-256 over the {@code 'V2'} version tag concatenated with the owner's
619	     * normalized E.164 telephone and last name; and {@code CHK} is a single Luhn check digit over
620	     * the digits of {@code '<REGION><FY><HASH8>'} (e.g. {@code 'V2NSW26A2B3C4D5'}). Mixing in the
621	     * version tag guarantees the id differs from the value version 1 would have produced. No sequence
622	     * number is used, so the id is a pure function of the owner's own identity fields.
623	     */
624	    private static String memberId(String postcode, String telephone, String lastName,
625	                                   LocalDate registrationDate) {
626	        String region = LocalityDeriver.identifierRegion(postcode);
627	        String fiscalYear = String.format("%02d",
628	            FiscalYearDeriver.fiscalYear(registrationDate) % 100);
629	        String hash8 = sha256Hex8(IDENTITY_VERSION_TAG
630	            + (telephone == null ? "" : telephone)
631	            + (lastName == null ? "" : lastName));
632	        String base = region + fiscalYear + hash8;
633	        return base + CheckDigitDeriver.checkDigit(base);
634	    }
635	
636	    /**
637	     * De-duplicates a computed {@code memberId} against the ids already assigned to existing owners.
638	     * If {@code base} is not currently in use it is returned unchanged; otherwise {@code '-<n>'} is
639	     * appended with the smallest {@code n} of 2 or more that yields an id no existing owner holds
640	     * (e.g. a second collision on {@code 'NSW261A2B3C4D4'} becomes {@code 'NSW261A2B3C4D4-2'}, a
641	     * third {@code 'NSW261A2B3C4D4-3'}, and so on).
642	     */
643	    private String deduplicateMemberId(String base) {
644	        Set<String> existing = this.clinicService.findAllOwners().stream()
645	            .map(Owner::getMemberId)
646	            .filter(id -> id != null)
647	            .collect(Collectors.toSet());
648	        if (!existing.contains(base)) {
649	            return base;
650	        }
651	        int n = 2;
652	        while (existing.contains(base + "-" + n)) {
653	            n++;
654	        }
655	        return base + "-" + n;
656	    }
657	
658	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
659	    private static String sha256Hex8(String s) {
660	        try {
661	            byte[] digest = MessageDigest.getInstance("SHA-256")
662	                .digest(s.getBytes(StandardCharsets.UTF_8));
663	            StringBuilder sb = new StringBuilder(8);
664	            for (int i = 0; i < 4; i++) {
665	                sb.append(String.format("%02X", digest[i]));
666	            }
667	            return sb.toString();
668	        }
669	        catch (NoSuchAlgorithmException e) {
670	            throw new IllegalStateException("SHA-256 not available", e);
671	        }
672	    }
673	
674	    /**
675	     * Counts the existing owners that share the given first name and last name, compared
676	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
677	     * owner currently being created is saved), so it reflects how many namesakes preceded the
678	     * new owner.
679	     */
680	    private int countNamesakes(String firstName, String lastName) {
681	        return (int) this.clinicService.findAllOwners().stream()
682	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
683	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
684	            .count();
685	    }
686	
687	    /**
688	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
689	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
690	     * national one, a single leading {@code '0'} is dropped, and the default country code
691	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
692	     * national number must have the length required by its country code ({@code '+61'} requires 9
693	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
694	     * raised (reported to the client as 400).
695	     */
696	    private static String toE164(String telephone) {
697	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
698	        String digits;
699	        if (cleaned.startsWith("+")) {
700	            digits = cleaned.substring(1);
701	        } else {
702	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
703	            digits = "61" + national;
704	        }
705	        if (!digits.matches("[0-9]{8,15}")) {
706	            throw new InvalidTelephoneException(
707	                "telephone must form a valid E.164 number with 8 to 15 digits");
708	        }
709	        validateNationalLength(digits);
710	        return "+" + digits;
711	    }
712	
713	    /** National-number length required for each supported country code (digits after the code). */
714	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
715	        "61", 9, "1", 10);
716	
717	    /**
718	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
719	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
720	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
721	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
722	     */
723	    private static void validateNationalLength(String digits) {
724	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
725	            String code = entry.getKey();
726	            if (digits.startsWith(code)) {
727	                int nationalLength = digits.length() - code.length();
728	                if (nationalLength != entry.getValue()) {
729	                    throw new InvalidTelephoneException(
730	                        "telephone national number must have " + entry.getValue()
731	                            + " digits for country code +" + code);
732	                }
733	                return;
734	            }
735	        }
736	    }
737	
738	    /**
739	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
740	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
741	     * any 4-digit postcode.
742	     */
743	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
744	        "NSW", new int[] {2000, 2099},
745	        "VIC", new int[] {3000, 3099},
746	        "QLD", new int[] {4000, 4099});
747	
748	    /**
749	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
750	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
751	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
752	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
753	     * no known region accepts any 4-digit postcode. A violation raises an
754	     * {@link InvalidPostcodeException} (reported to the client as 400).
755	     */
756	    private static void validatePostcode(String city, String postcode) {
757	        if (isBlank(postcode)) {
758	            return;
759	        }
760	        if (!postcode.matches("[0-9]{4}")) {
761	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
762	        }
763	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
764	        if (range == null) {
765	            return;
766	        }
767	        int value = Integer.parseInt(postcode);
768	        if (value < range[0] || value > range[1]) {
769	            throw new InvalidPostcodeException(
770	                "postcode is out of range for the owner's city region");
771	        }
772	    }
773	
774	    /**
775	     * Disposable email domains that are rejected outright: an owner whose email domain is one of
776	     * these is refused with a 400. Compared case-insensitively (the email is lower-cased before the
777	     * check).
778	     */
779	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
780	        "mailinator.com", "tempmail.com", "guerrillamail.com");
781	
782	    /**
783	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
784	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
785	     * is raised (reported to the client as 400). Its domain must not be on the disposable-domain
786	     * blocklist ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}), otherwise
787	     * an {@link InvalidEmailException} is likewise raised (400). A valid value is returned lower-cased
788	     * so it is stored and returned in canonical form.
789	     */
790	    private static String normalizeEmail(String email) {
791	        if (isBlank(email)) {
792	            return null;
793	        }
794	        String trimmed = email.trim();
795	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
796	            throw new InvalidEmailException("email must be a syntactically valid address");
797	        }
798	        String normalized = trimmed.toLowerCase(Locale.ROOT);
799	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
800	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
801	            throw new InvalidEmailException("email domain is on the disposable-domain blocklist");
802	        }
803	        return normalized;
804	    }
805	}
